                  2'd0: r0 <= imm_reg;
                  2'd1: r1 <= imm_reg;
                  2'd2: r2 <= imm_reg;
                  2'd3: r3 <= imm_reg;
                endcase
                pc    <= pc + 16'd1;
                state <= ST_FETCH;
              end

              OP_SETEV:
              begin
                event_set <= 1'b1;
                event_id  <= ev_id;
                pc        <= pc + 16'd1;
                state     <= ST_FETCH;
              end

