  output [7:0] uo_out,
  output [7:0] uio_out,
  output [7:0] uio_oe
);
  wire s0;
  wire [2:0] s1;
  wire [15:0] s2;
  wire [15:0] s3;
  wire s4;
  wire [2:0] s5;
  wire [15:0] s6;
  wire [15:0] s7;
  wire s8;
