  wire s46;
  wire s47;
  wire [15:0] s48;
  wire [15:0] s49;
  wire s50;
  wire [1:0] s51;
  wire [2:0] s52;
  wire s53;
  wire s54;
  wire [1:0] s55;
  wire [15:0] s56;
  wire s57;
  wire [15:0] s58;
  wire s59;
  wire s60;
  wire [15:0] s61;
  wire s62;
  wire s63;
  wire s64;
  wire [15:0] s65;
  wire [15:0] s66;
  wire \sda-in ;
  wire spics_flash;
  wire spi_clock;
  wire spics_ram;
  wire [3:0] qspi_data_oe;
  wire [3:0] qspi_data_in;
  wire [3:0] qspi_data_out;
  wire [7:0] s67;
  wire s68;
  wire s69;
  wire s70;
  wire s71;
  wire s72;
  assign qspi_data_in[0] = uio_in[1];
  assign qspi_data_in[1] = uio_in[2];
  assign qspi_data_in[2] = uio_in[4];
  assign qspi_data_in[3] = uio_in[5];
  assign \sda-in  = uio_in[7];
  assign s68 = ui_in[7];
  // shared_alu_arbiter3
  shared_alu_arbiter3 shared_alu_arbiter3_i0 (
    .clk( clk ),
    .rst_n( rst_n ),
    .req0( s0 ),
    .op0( s1 ),
    .a0( s2 ),
    .b0( s3 ),
    .req1( s4 ),
