  );
  // tiny_core
  tiny_core tiny_core_i2 (
    .RESET_PC( 16'b10 ),
    .clk( clk ),
    .rst_n( rst_n ),
    .core_en( rst_n ),
    .alu_done( s8 ),
    .alu_result( s9 ),
    .mem_done( s21 ),
    .mem_rdata( s22 ),
    .event_flags( s20 ),
    .pin_done( s23 ),
    .pin_rdata( s24 ),
    .uart_done( s25 ),
    .uart_rdata( s26 ),
    .alu_req( s0 ),
    .alu_op( s1 ),
    .alu_a( s2 ),
    .alu_b( s3 ),
