    .mem_write( s28 ),
    .mem_target( s29 ),
    .mem_addr( s30 ),
    .mem_wdata( s31 ),
    .event_set( s12 ),
    .event_clr( s13 ),
    .event_id( s14 ),
    .pin_req( s32 ),
    .pin_op( s33 ),
    .pin_id( s34 ),
    .pin_wdata( s35 ),
    .uart_req( s36 ),
    .uart_op( s37 ),
    .uart_wdata( s38 )
  );
  // tiny_core
  tiny_core tiny_core_i3 (
    .RESET_PC( 16'b11 ),
    .clk( clk ),
    .rst_n( rst_n ),
